create table if not exists public.hot_seat_session_hosts (
 id uuid primary key default gen_random_uuid(), session_id uuid not null references public.hot_seat_hosts(id) on delete cascade, host_order integer not null, alias text not null, avatar text, media_url text, is_active boolean not null default true, created_at timestamptz not null default now(), unique(session_id,host_order), unique(session_id,alias));
alter table public.hot_seat_session_hosts enable row level security;
drop policy if exists "hotseat session hosts active read" on public.hot_seat_session_hosts;
create policy "hotseat session hosts active read" on public.hot_seat_session_hosts for select to authenticated using (exists(select 1 from public.hot_seat_hosts h where h.id=session_id and h.is_active=true and h.ends_at>now()));
create or replace function public.admin_hot_seat_add_host(p_session_id uuid,p_alias text,p_avatar text default null,p_media_url text default null,p_host_order integer default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); h public.hot_seat_hosts%rowtype; next_order integer; r public.hot_seat_session_hosts%rowtype; begin if not private.is_admin(uid) then raise exception 'Admin access required'; end if; if length(trim(coalesce(p_alias,'')))=0 or length(trim(p_alias))>80 then raise exception 'Host name must be 1-80 characters'; end if; select * into h from public.hot_seat_hosts where id=p_session_id and is_active=true; if not found then raise exception 'Active Hot Seat session not found'; end if; select coalesce(max(host_order)+1,1) into next_order from public.hot_seat_session_hosts where session_id=p_session_id; next_order:=coalesce(p_host_order,next_order); if next_order<1 or next_order>h.max_hosts then raise exception 'Host slot is outside the configured limit'; end if; if exists(select 1 from public.hot_seat_session_hosts where session_id=p_session_id and host_order=next_order) then raise exception 'Host slot already occupied'; end if; insert into public.hot_seat_session_hosts(session_id,host_order,alias,avatar,media_url) values(p_session_id,next_order,trim(p_alias),p_avatar,p_media_url) returning * into r; insert into public.admin_audit_log(admin_user_id,action,metadata) values(uid,'HOT_SEAT_HOST_ADD',jsonb_build_object('session_id',p_session_id,'slot',next_order,'alias',trim(p_alias))); return to_jsonb(r); end $$;
create or replace function public.admin_hot_seat_remove_host(p_session_host_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); r public.hot_seat_session_hosts%rowtype; begin if not private.is_admin(uid) then raise exception 'Admin access required'; end if; update public.hot_seat_session_hosts set is_active=false where id=p_session_host_id returning * into r; if not found then raise exception 'Host slot not found'; end if; insert into public.admin_audit_log(admin_user_id,action,metadata) values(uid,'HOT_SEAT_HOST_REMOVE',jsonb_build_object('session_host_id',p_session_host_id)); return to_jsonb(r); end $$;
revoke all on function public.admin_hot_seat_add_host(uuid,text,text,text,integer) from public,anon,authenticated; revoke all on function public.admin_hot_seat_remove_host(uuid) from public,anon,authenticated; grant execute on function public.admin_hot_seat_add_host(uuid,text,text,text,integer) to authenticated; grant execute on function public.admin_hot_seat_remove_host(uuid) to authenticated;